mapper.select:
select *
from COLLECT_INTERFACES t
where t.LINK_IP = #{remoteIp}

select *
from (
select round(PORT_IN_SPEED/8000, 2) as value,
COLLECT_TIME as endTime
from COLLECT_INTERFACES
where ASSET_ID = #{assetId}
and port_index = #{portIndex}
order by COLLECT_TIME desc
)
where rownum < #{rownum}

select *
from (
select round(PORT_OUT_SPEED/8000, 2) as value,
COLLECT_TIME as endTime
from COLLECT_INTERFACES
where ASSET_ID = #{assetId}
and port_index = #{portIndex}
order by COLLECT_TIME desc
)
where rownum < #{rownum}

select *
from COLLECT_INTERFACES e
where e.id = (
    select max(id)
    from COLLECT_INTERFACES
    where ASSET_ID = #{assetId}
      and PORT_INDEX_RANK = #{portIndexRank}
)

select *
from (
select RX_POWER as value,
COLLECT_TIME as endTime
from COLLECT_INTERFACES
where ASSET_ID = #{assetId}
and port_index = #{portIndex}
and RX_POWER is not null
order by COLLECT_TIME desc
)
where rownum < #{rownum}

select *
from (
select TX_POWER as value,
COLLECT_TIME as endTime
from COLLECT_INTERFACES
where ASSET_ID = #{assetId}
and port_index = #{portIndex}
and TX_POWER is not null
order by COLLECT_TIME desc
)
where rownum < #{rownum}

select *
from collect_interfaces
where ASSET_ID = #{assetId}
  and PORT_NAME = #{portName}

select portName
from collect_interfaces
where ASSET_ID = #{assetId}
  and port_index = #{portFullName}
